#!/usr/bin/env python3
"""Decode / encode Fiber Twig save files (saves/*.sav, generated by the original game).

Format
------
An INI-like text file where every byte has 0x33 (51) added, e.g.

    76 A8 A5 A5 98 A1 A7 7F 98 A9 98 9F 70 55 63 55   -> (each - 0x33)
    43 75 72 72 65 6E 74 4C 65 76 65 6C 3D 22 30 22   ->  'CurrentLevel="0"'

Known keys (offsets inside the decoded text, 1 based style used by the
community save editor) are listed in the original repository's Rust tool.

Usage:
    python3 save_codec.py decode saves/LEVEL_01.sav
    python3 save_codec.py encode decoded.ini out.sav
"""
import sys


def decode(raw: bytes) -> bytes:
    """Records are separated by literal CRLF; the record bytes are shifted by +0x33."""
    parts = raw.split(b"\r\n")
    return b"\r\n".join(bytes((b - 0x33) & 0xFF for b in p) for p in parts)


def encode(text: bytes) -> bytes:
    parts = text.split(b"\r\n")
    return b"\r\n".join(bytes((b + 0x33) & 0xFF for b in p) for p in parts)


def main():
    mode, src, dst = sys.argv[1], sys.argv[2], (sys.argv[3] if len(sys.argv) > 3 else None)
    raw = open(src, "rb").read()
    out = decode(raw) if mode == "decode" else encode(raw)
    if dst:
        open(dst, "wb").write(out)
    else:
        sys.stdout.write(out.decode("latin-1"))


if __name__ == "__main__":
    main()
